package entity;

import java.awt.Color;
import java.awt.Graphics2D;
import main.GamePanel;

/**
 * The class represents a single visual particle generated by
 * an Entity.
 */
public class Particle extends Entity {

    Entity generator;
    Color color;
    int size;
    int xd;
    int yd;

    /**
     * Constructs a new particle.
     * 
     * @param gp the gamepanel managing the game enviorement
     * @param generator the Entity that created this particle
     * @param color the color of the particle
     * @param size the size of the particle
     * @param speed the speed of the particle
     * @param maxLife the lifespan of the particle
     * @param xd the horizontal movement direction and intensity
     * @param yd the vertical movement direction and intensity
     */
    public Particle(GamePanel gp, Entity generator, Color color, 
        int size, int speed, int maxLife, int xd, int yd) {
        
        super(gp);
        this.generator = generator;
        this.color = color;
        this.size = size;
        this.speed = speed;
        this.maxLife = maxLife;
        this.xd = xd;
        this.yd = yd;

        life = maxLife;
        int offset = (gp.tileSize / 2) - (size / 2);
        worldX = generator.worldX + offset;
        worldY = generator.worldY + offset;
    } 
    
    /**
     * Updates the particles position and lifetime.
     */
    public void update() {
        life--;

        if (life < maxLife / 3) {
            yd++;
        }
        worldX += xd * speed;
        worldY += yd * speed;

        if (life == 0) {
            alive = false;
        }
    }

    /**
     * Renders the particle on the screen.
     */
    public void draw(Graphics2D g2) {
        int screenX = worldX - gp.player.worldX + gp.player.screenX;
        int screenY = worldY - gp.player.worldY + gp.player.screenY;

        g2.setColor(color);
        g2.fillRect(screenX, screenY, size, size);
    }
}
